CREATE TABLE Film (Film_ID NUMBER PRIMARY KEY, Titel VARCHAR2(60) NOT NULL, Dauer NUMBER(3));
CREATE TABLE Saal (Saal_ID NUMBER PRIMARY KEY, Name VARCHAR2(20) NOT NULL, Plaetze NUMBER(4));
CREATE TABLE Vorstellung (Film_ID NUMBER REFERENCES Film (Film_ID), Saal_ID NUMBER REFERENCES Saal (Saal_ID), Beginn DATE NOT NULL, Preis NUMBER(4,2), CONSTRAINT pk_vorstellung PRIMARY KEY (Film_ID, Saal_ID, Beginn));

